INSERT INTO public.products (id,name,brand,type,category,subcategory,volume,abv,origin,rating,badge,description,image_url,active,is_active,metadata) VALUES
('indri-trini','Indri Trini Single Malt','Indri','spirit','Spirits & beer','Made in India Single Malts','750ML','46%','Haryana, India',4.8,'Three Wood Award','Matured in Ex-Bourbon, Ex-Wine, and PX Sherry casks in Indri, Haryana. Notes of caramelized pineapple, vanilla, black tea, and sweet raisins.','https://londonspiritscompetition.com/cont/competitionSubmissions/imagePot/LondonSpiritsCompetition-02102022032809000000-6204daa99e8e5.jpg',TRUE,TRUE,'{"badge":"Three Wood Award"}'::jsonb),
('amrut-fusion','Amrut Fusion Single Malt','Amrut','spirit','Spirits & beer','Made in India Single Malts','750ML','50%','Bengaluru, India',4.9,'50% ABV Legend','Distilled from a fusion of Indian six-row barley and peated Scottish barley. Rich oak, dark chocolate fudge, and warm peat smoke.','https://www.1855thebottleshop.com/cdn/shop/products/amrut-fusion-single-malt-whisky-700ml-bottle.jpg?crop=center&height=800&v=1755690201&width=800',TRUE,TRUE,'{"badge":"50% ABV Legend"}'::jsonb),
('rampur-dc','Rampur Double Cask Single Malt','Rampur','spirit','Spirits & beer','Made in India Single Malts','750ML','45%','Uttar Pradesh, India',4.8,'Luxury Reserve','Handcrafted in the Himalayan foothills using American Bourbon barrels and European Oak Sherry casks. Tropical fruit and spiced oak.','https://cdn11.bigcommerce.com/s-0ddlsmhg83/images/stencil/original/products/2352/2576/rampur-double-cask-indian-single-malt-whisky__00405.1752495277.1280.1280__33148.1755241711.jpg?c=1',TRUE,TRUE,'{"badge":"Luxury Reserve"}'::jsonb),
('gianchand','GianChand Single Malt Whisky','DeVans','spirit','Spirits & beer','Made in India Single Malts','750ML','42.8%','Jammu, India',4.7,'Himalayan Malt','Crafted in Jammu with pristine Himalayan water. Delicate pineapple candy drop sweetness, vanilla backbone, and subtle barley oil.','https://www.paulsliquor.com.au/cdn/shop/files/GainChand-Single-malt.png?v=1717137872',TRUE,TRUE,'{"badge":"Himalayan Malt"}'::jsonb),
('glenfiddich-12','Glenfiddich 12 YO Single Malt','Glenfiddich','spirit','Spirits & beer','Single Malt','750ML','40%','Speyside, Scotland',4.8,'Valley of the Deer','Matured in Oloroso sherry and bourbon oak casks for 12 years. Fresh pear, butterscotch, cream, and subtle oak.','https://www.instacart.com/assets/domains/product-image/file/large_4595f1dd-866f-4876-b275-63dd3ec06f1e.jpeg',TRUE,TRUE,'{"badge":"Valley of the Deer"}'::jsonb),
('glenlivet-12','The Glenlivet 12 YO Double Oak','The Glenlivet','spirit','Spirits & beer','Single Malt','750ML','40%','Speyside, Scotland',4.8,'Speyside Benchmark','Smooth floral aroma with bright summer citrus, roasted hazelnut, and sweet vanilla custard.','https://paneco-sg-moonshine-production.s3.ap-southeast-1.amazonaws.com/shgwi0eiuh7jaqb76x7tlw6ddvcq',TRUE,TRUE,'{"badge":"Speyside Benchmark"}'::jsonb),
('macallan-12','The Macallan Double Cask 12 YO','The Macallan','spirit','Spirits & beer','Single Malt','750ML','40%','Speyside, Scotland',4.9,'Collector Favourite','Harmonious marriage of American and European Oloroso sherry-seasoned oak casks. Honeyed ginger, citrus marmalade, and sultanas.','https://brand-assets.edrington.com/transform/7020a501-9c82-47e3-b0df-03faaa2e40a2/MAC-2023-Double-Cask-12YO-Bottle--70cl-RGB-WEB-initial?io=transform%3Afit%2Cwidth%3A599%2Cheight%3A599&quality=100',TRUE,TRUE,'{"badge":"Collector Favourite"}'::jsonb),
('talisker-10','Talisker 10 YO Single Malt','Talisker','spirit','Spirits & beer','Single Malt','750ML','45.8%','Isle of Skye, Scotland',4.8,'Maritime Peat','Made by the sea on the Isle of Skye. Powerful coastal sea-salt spray, cracked black pepper, and sweet orchard smoke.','https://www.finescottishhampers.com/image_resize/back/w1500/products/502/71PfYLlDUoL.ACSL1500.jpg',TRUE,TRUE,'{"badge":"Maritime Peat"}'::jsonb),
('jw-black','Johnnie Walker Black Label 12 YO','Johnnie Walker','spirit','Spirits & beer','Blended Scotch','750ML','40%','Scotland',4.8,'All-Time Favourite','Iconic 12-year aged blend of whiskies from all four corners of Scotland bursting with dark fruits, sweet vanilla, and signature peat smoke.','https://images.ctfassets.net/waruwpig3jxu/55BPOqOreCU44edDswoigY/153eae9e783bce07830134d161a349b3/black-750ml_producthero_fullfront_desktop.webp?q=80&w=2560',TRUE,TRUE,'{"badge":"All-Time Favourite"}'::jsonb),
('monkey-shoulder','Monkey Shoulder Blended Malt','Monkey Shoulder','spirit','Spirits & beer','Blended Scotch','750ML','40%','Scotland',4.9,'100% Malt Whisky','Small-batch blend of prized Speyside single malts matured in first-fill ex-Bourbon barrels. Zesty orange, mellow vanilla, and spiced oak.','https://static.maxi.rs/medias/sys_master/products/h8b/he5/9243860762654.jpg?buildNumber=7314f1c628b31db1405f1b35130f0cc5c045b6859f4cb8a9cf45d1646bf42030',TRUE,TRUE,'{"badge":"100% Malt Whisky"}'::jsonb),
('chivas-12','Chivas Regal 12 YO','Chivas Regal','spirit','Spirits & beer','Blended Scotch','750ML','40%','Scotland',4.7,'Pour Lineup','Cask-matured Speyside richness with wild herbs, heather honey, creamy butterscotch, and orchard apples.','https://internetwines.com/cdn/shop/files/Chivas12_2023_4480x.jpg?v=1688952639',TRUE,TRUE,'{"badge":"Pour Lineup"}'::jsonb),
('ballantines-finest','Ballantine''s Finest Blended Scotch','Ballantine''s','spirit','Spirits & beer','Blended Scotch','750ML','40%','Scotland',4.6,'Party Essential','Refined, balanced blend with light heather honey, milk chocolate, red apple, and vanilla finish.','https://www.continente.pt/on/demandware.static/-/Sites-col-master-catalog/default/dw78d2f8d9/images/col/205/2050153-frente.jpg',TRUE,TRUE,'{"badge":"Party Essential"}'::jsonb),
('jameson','Jameson Triple Distilled Irish Whiskey','Jameson','spirit','Spirits & beer','Irish Whiskey','750ML','40%','Dublin, Ireland',4.8,'Triple Distilled','Triple-distilled Irish pot still and fine grain whiskey. Light floral fragrance peppered with spicy wood and sweet sherry nuttiness.','https://www.vlastni-etikety.cz/design/labels/galerie/jameson_3.jpg',TRUE,TRUE,'{"badge":"Triple Distilled"}'::jsonb),
('jack-daniels','Jack Daniel''s Old No. 7 Tennessee','Jack Daniel''s','spirit','Spirits & beer','Bourbon','750ML','40%','Tennessee, USA',4.8,'Charcoal Mellowed','Mellowed drop by drop through 10 feet of sugar maple charcoal. Smooth caramel, toasted oak, banana, and smoky vanilla.','https://www.bestwaywholesale.co.uk/img/products/1000/8/5099873089798.jpg',TRUE,TRUE,'{"badge":"Charcoal Mellowed"}'::jsonb),
('jim-beam-white','Jim Beam Kentucky Straight Bourbon','Jim Beam','spirit','Spirits & beer','Bourbon','750ML','40%','Kentucky, USA',4.6,'World #1 Bourbon','Aged 4 years in newly charred American white oak barrels. Oaky vanilla aroma with medium-bodied caramel and sweet corn warmth.','https://drinky.ch/cdn/shop/files/drinky_produkte_bilder_jim_beam_bourbon_whiskey_einzelflasche.jpg?v=1718983044',TRUE,TRUE,'{"badge":"World #1 Bourbon"}'::jsonb),
('makers-mark','Maker''s Mark Handmade Bourbon','Maker''s Mark','spirit','Spirits & beer','Bourbon','750ML','45%','Kentucky, USA',4.8,'Red Wax Seal','Crafted with soft red winter wheat instead of rye for a zero-bitterness palate bursting with butterscotch, woody oak, and vanilla.','https://woodencork.com/cdn/shop/products/00085246139431_C1N1_en-US0927_s01.jpg?v=1679527951',TRUE,TRUE,'{"badge":"Red Wax Seal"}'::jsonb),
('greater-than','Greater Than London Dry Gin','Nao Spirits','spirit','Spirits & beer','Craft Gin','750ML','40%','Goa, India',4.7,'India First Craft Gin','Distilled in a copper pot still in Goa with 9 botanicals including juniper, lemongrass, ginger, and chamomile. Clean citrus zing.','https://www.paulsliquor.com.au/cdn/shop/products/greater-than-london-dry-gin.jpg?v=1669087955',TRUE,TRUE,'{"badge":"India First Craft Gin"}'::jsonb),
('stranger-sons','Stranger & Sons Indian Spirited Gin','Third Eye Distillery','spirit','Spirits & beer','Craft Gin','750ML','42.8%','Goa, India',4.8,'3D Citrus Peel','Bold botanical chorus of Gondhoraj limes, Nagpur oranges, nimble limes, black pepper, nutmeg, and coriander seed.','https://www.theginguild.com/wp-content/uploads/2020/11/stranger-and-sons-indian-spirited-gin.jpg',TRUE,TRUE,'{"badge":"3D Citrus Peel"}'::jsonb),
('jaisalmer-gin','Jaisalmer Indian Craft Gin','Radico Khaitan','spirit','Spirits & beer','Craft Gin','750ML','42.8%','Uttar Pradesh, India',4.8,'Royal Oasis Gin','Infused with 11 botanicals including Darjeeling green tea leaves, vetiver, sweet orange peel, cubeb berries, and lemongrass.','https://m.media-amazon.com/images/I/61mI0%2BFo1kL._AC_SL1500_.jpg',TRUE,TRUE,'{"badge":"Royal Oasis Gin"}'::jsonb),
('hendricks-gin','Hendrick''s Scottish Small Batch Gin','Hendrick''s','spirit','Spirits & beer','Craft Gin','750ML','41.4%','Girvan, Scotland',4.9,'Rose & Cucumber','Unusual distillation in Bennett and Carter-Head stills infused with Bulgarian Rosa Damascena petals and refreshing cucumber.','https://mrliquor.com.au/cdn/shop/products/Hendrick_s_Gin_700mL-1.jpg?v=1573617605',TRUE,TRUE,'{"badge":"Rose & Cucumber"}'::jsonb),
('corona-extra','Corona Extra Mexican Pint','Corona','spirit','Spirits & beer','Beers','330ML','4.5%','Mexico / India',4.8,'Serve with Lime','Crisp, sun-drenched pale lager with light honey-malt sweetness and refreshing hop character.','https://godrinks.com/cdn/shop/files/CoronaExtra35.5cl.png?v=1709626396',TRUE,TRUE,'{"badge":"Serve with Lime"}'::jsonb),
('hoegaarden','Hoegaarden Witbier Pint','Hoegaarden','spirit','Spirits & beer','Beers','330ML','4.9%','Belgium',4.9,'Belgian Wheat','Unfiltered Belgian white beer brewed with Curaçao orange peel and coriander seeds for a velvety, cloud-like citrus finish.','https://images.cdn.europe-west1.gcp.commercetools.com/723b2575-66c7-4d92-ae49-82bf1d168d26/00-720201-0201629368-lCKDV670.jpg',TRUE,TRUE,'{"badge":"Belgian Wheat"}'::jsonb),
('bira-white','Bira 91 White Ale Can','Bira 91','spirit','Spirits & beer','Beers','500ML','4.7%','India',4.7,'Craft Wheat','Deliciously cloudy wheat ale with low bitterness, bright orange peel aroma, and a touch of Indian coriander.','https://images.news18.com/static-bengali/uploads/2025/11/Bira-Beer-Image-2025-11-1a63df653c88ca8c4da1deac7e47aac3.jpg?height=620&impolicy=website&width=827',TRUE,TRUE,'{"badge":"Craft Wheat"}'::jsonb),
('bud-magnum','Budweiser Magnum Strong Bottle','Budweiser','spirit','Spirits & beer','Beers','650ML','6.5%','India',4.7,'All-Time Favourite','Beechwood-aged strong super premium lager with roasted malt sweetness and crisp herbal hop balance.','https://onlinealcohol.in/storage/2020/09/Budweiser-Magnum-330-ml.jpg',TRUE,TRUE,'{"badge":"All-Time Favourite"}'::jsonb),
('kf-ultra','Kingfisher Ultra Smooth Lager','Kingfisher','spirit','Spirits & beer','Beers','650ML','5%','India',4.6,'Emperor of Good Times','Brewed from the finest imported malts and hops for a golden appearance and exceptionally crisp, smooth taste.','https://boozeexpress.com.au/cdn/shop/files/KingfisherUltraPremiumIndianLagerBeerBottles650mL.png?v=1772318650',TRUE,TRUE,'{"badge":"Emperor of Good Times"}'::jsonb),
('grey-goose','Grey Goose French Vodka','Grey Goose','spirit','Spirits & beer','Vodka & Rum','750ML','40%','Cognac, France',4.9,'Ultra-Premium Vodka','Distilled from soft winter wheat from Picardie and Gensac spring water. Creamy almond pastry notes and a silky, clean finish.','https://www.eightpm.co.nz/cdn/shop/products/grey-goose-premium-vodka-700ml-681944.jpg?v=1624199749',TRUE,TRUE,'{"badge":"Ultra-Premium Vodka"}'::jsonb),
('absolut-vodka','Absolut Original Swedish Vodka','Absolut','spirit','Spirits & beer','Vodka & Rum','750ML','40%','Åhus, Sweden',4.7,'Zero Added Sugar','Continuous distillation using winter wheat and deep well water in Åhus. Rich, full-bodied grain character with dried fruit hints.','https://assets.iceland.co.uk/i/iceland/absolut_original_swedish_vodka_70cl_71748_T1.jpg',TRUE,TRUE,'{"badge":"Zero Added Sugar"}'::jsonb),
('old-monk-legend','Old Monk The Legend Dark Rum','Mohan Meakin','spirit','Spirits & beer','Vodka & Rum','1000ML','42.8%','Ghaziabad, India',4.9,'Cult Classic','Iconic monk-head decanter filled with vatted dark Indian rum bursting with roasted coffee, dark caramel, vanilla, and jaggery.','https://globalspirits.co.nz/cdn/shop/products/0029157_old-monk-the-legend-rum-1-ltr_grande.jpg?v=1662800695',TRUE,TRUE,'{"badge":"Cult Classic"}'::jsonb),
('bacardi-carta-blanca','Bacardí Carta Blanca Superior White Rum','Bacardí','spirit','Spirits & beer','Vodka & Rum','750ML','42.8%','Puerto Rico / India',4.6,'Mojito Essential','Aged in American white oak barrels and shaped through a secret blend of charcoal for floral, vanilla, and citrus cocktail perfection.','https://www.drinksinc.com/cdn/shop/files/bcc97411-02d1-4dd7-8d64-dc14a57b638c.jpg?v=1763386193&width=900',TRUE,TRUE,'{"badge":"Mojito Essential"}'::jsonb),
('patron-silver','Patrón Silver 100% Blue Weber Tequila','Patrón','spirit','Spirits & beer','Vodka & Rum','750ML','40%','Jalisco, Mexico',4.9,'100% De Agave','Handcrafted from the finest 100% Weber Blue Agave in Jalisco. Smooth roasted agave, bright citrus, and light white pepper.','https://cdn.shopify.com/s/files/1/0099/0045/8042/files/2025_bottle_silver-mjllDTu1sqOB5b.jpg?v=1770993338',TRUE,TRUE,'{"badge":"100% De Agave"}'::jsonb),
('moet-imperial','Moët & Chandon Impérial Brut Champagne','Moët & Chandon','wine','Wine','Wine & Champagne','750ML','12%','Épernay, France',4.9,'Grand Champagne','Vibrant intensity of green apple and citrus fruit, mineral freshness, white blossoms, and blonde brioche elegance.','https://digitalcontent.api.tesco.com/v2/media/ghs/af98ad9a-31fa-4afd-ac96-4be5f2b1142d/938ff3c3-dbe3-4d0d-86b6-de9fa851fdcf_1910783801.jpeg',TRUE,TRUE,'{"badge":"Grand Champagne"}'::jsonb),
('sula-dindori','Sula Dindori Reserve Shiraz','Sula Vineyards','wine','Wine','Wine & Champagne','750ML','14%','Nashik, India',4.7,'Estate Reserve','Matured in American oak barrels for 12 months. Silky red berries, mocha, vanilla bean, and smoky black pepper.','https://cf.shopee.sg/file/c45edb0c19bf70ea14b0d3a8a80d6183',TRUE,TRUE,'{"badge":"Estate Reserve"}'::jsonb),
('jacobs-creek-chard','Jacob''s Creek Classic Chardonnay','Jacob''s Creek','wine','Wine','Wine & Champagne','750ML','13%','South Eastern Australia',4.6,'Crisp Australian White','Ripe melon and white peach flavours layered with zesty lemon curd and subtle toasted oak creaminess.','https://cdn.metcash.media/image/upload/f_auto%2Cc_limit%2Cw_1500%2Cq_auto/igashop/images/6600933',TRUE,TRUE,'{"badge":"Crisp Australian White"}'::jsonb),
