-- 43 catalogue entries and 148 legacy prices. Prices are explicitly unverified snapshots.
ON CONFLICT (id) DO UPDATE SET name=excluded.name,brand=excluded.brand,type=excluded.type,category=excluded.category,subcategory=excluded.subcategory,volume=excluded.volume,abv=excluded.abv,origin=excluded.origin,rating=excluded.rating,badge=excluded.badge,description=excluded.description,image_url=excluded.image_url,active=excluded.active,is_active=excluded.is_active,metadata=excluded.metadata,updated_at=now();

ON CONFLICT (product_id,city) DO UPDATE SET price=excluded.price,source_type='import',source_label=excluded.source_label,source_url=NULL,verified=false,updated_at=now();
